//! Key and login management over HTTP, through the real router: an admin with 2FA
//! steps up once per window, opens the keyring with a factor in the body, and every
//! change lands in the audit trail.

use std::sync::Arc;

use axum::{
    body::Body,
    http::{Method, Request, StatusCode},
    Router,
};
use base64::Engine;
use http_body_util::BodyExt;
use serde_json::{json, Value};
use tempfile::TempDir;
use tower::ServiceExt;
use veld::{
    config::ServerConfig,
    handlers::{build_protected_routes, MultiUserMemoryManager},
};

const PASS: &str = "security-api-correct-horse-S1";

struct Api {
    app: Router,
}

struct Reply {
    status: StatusCode,
    body: Value,
    text: String,
    csp: Option<String>,
}

impl Api {
    async fn call(
        &self,
        method: Method,
        uri: &str,
        token: [REDACTED],
        step_up: Option<&str>,
        body: Option<Value>,
    ) -> Reply {
        let mut req = Request::builder().method(method).uri(uri);
        if let Some(t) = token {
            req = req.header("authorization", format!("Bearer {t}"));
        }
        if let Some(c) = step_up {
            req = req.header("x-veld-step-up", c);
        }
        let req = match body {
            Some(b) => req
                .header("content-type", "application/json")
                .body(Body::from(b.to_string())),
            None => req.body(Body::empty()),
        }
        .unwrap();
        let resp = self.app.clone().oneshot(req).await.unwrap();
        let status = resp.status();
        let csp = resp
            .headers()
            .get("content-security-policy")
            .map(|v| v.to_str().unwrap().to_string());
        let bytes = resp.into_body().collect().await.unwrap().to_bytes();
        let text = String::from_utf8_lossy(&bytes).into_owned();
        Reply {
            status,
            body: serde_json::from_slice(&bytes).unwrap_or(Value::Null),
            text,
            csp,
        }
    }

    async fn get(&self, uri: &str, token: &str) -> Reply {
        self.call(Method::GET, uri, Some(token), None, None).await
    }

    async fn post(&self, uri: &str, token: &str, body: Value) -> Reply {
        self.call(Method::POST, uri, Some(token), None, Some(body))
            .await
    }

    async fn post_up(&self, uri: &str, token: &str, code: &str, body: Value) -> Reply {
        self.call(Method::POST, uri, Some(token), Some(code), Some(body))
            .await
    }

    async fn login(&self, username: &str, password: &str, totp: Option<String>) -> Reply {
        self.call(
            Method::POST,
            "/api/user_auth/login",
            None,
            None,
            Some(json!({ "username": username, "password": password, "totp": totp })),
        )
        .await
    }
}

fn ok(reply: &Reply, what: &str) {
    assert!(
        reply.status.is_success(),
        "{what}: {} {}",
        reply.status,
        reply.text
    );
}

#[tokio::test(flavor = "multi_thread")]
async fn an_admin_with_2fa_manages_keys_and_logins_over_http() {
    let dir = TempDir::new().unwrap();
    let storage = dir.path().join("data");
    std::fs::create_dir_all(&storage).unwrap();
    std::env::set_var("VELD_USER_AUTH_ENABLED", "true");
    std::env::set_var("VELD_API_KEYS", "security-admin-api-test-key");
    std::env::set_var("VELD_LAZY_CROSS_ENCODER", "1");
    std::env::set_var("VELD_MASTER_PASSPHRASE", PASS);
    std::env::set_var(
        "VELD_KEYSTORE_PATH",
        dir.path().join("global-keystore.json"),
    );
    std::env::remove_var("VELD_KEYRING_PATH");
    std::env::remove_var("VELD_KMS_WRAP_KEY");

    veld::keystore::open_record_keys(&storage.join("alice").join("storage").join("keystore.json"))
        .unwrap()
        .expect("a tenant keystore before the keyring");
    let cfg = ServerConfig {
        storage_path: storage.clone(),
        backup_enabled: false,
        ..ServerConfig::default()
    };
    let mgr = Arc::new(MultiUserMemoryManager::new(storage.clone(), cfg).unwrap());
    let api = Api {
        app: build_protected_routes(mgr, false)
            .layer(axum::middleware::from_fn(veld::auth::auth_middleware)),
    };

    // An admin with 2FA.
    ok(
        &api.call(
            Method::POST,
            "/api/user_auth/register",
            None,
            None,
            Some(json!({ "username": "root", "password": "[REDACTED]" })),
        )
        .await,
        "register the first admin",
    );
    let token = api.login("root", "root-password-1", None).await.body["session_token"]
        .as_str()
        .unwrap()
        .to_string();
    let enroll = api
        .post("/api/user_auth/2fa/enroll", &token, json!({}))
        .await;
    ok(&enroll, "enrol 2FA");
    let totp = totp_rs::TOTP::from_url(enroll.body["provisioning_uri"].as_str().unwrap()).unwrap();
    ok(
        &api.post(
            "/api/user_auth/2fa/confirm",
            &token,
            json!({ "totp": totp.generate_current().unwrap() }),
        )
        .await,
        "confirm 2FA",
    );

    // Status needs no step-up; a change does.
    let status = api.get("/api/user_auth/admin/keys/status", &token).await;
    ok(&status, "key status");
    assert!(status.body["status"]["keyring"].is_null());
    let scopes: Vec<_> = status.body["status"]["keystores"]
        .as_array()
        .unwrap()
        .iter()
        .map(|k| k["scope"].as_str().unwrap().to_string())
        .collect();
    assert_eq!(scopes, ["global", "alice"]);
    let refused = api
        .post(
            "/api/user_auth/admin/keys/init",
            &token,
            json!({ "passphrase": PASS }),
        )
        .await;
    assert_eq!(refused.body["code"], "STEP_UP_REQUIRED", "{}", refused.text);

    // A code steps up one session once; a second session cannot reuse it. Unlocking
    // an account is a cheap change, so the code is still inside its window.
    let second = api
        .login(
            "root",
            "root-password-1",
            Some(totp.generate_current().unwrap()),
        )
        .await;
    let token2 = second.body["session_token"].as_str().unwrap().to_string();
    let code = totp.generate_current().unwrap();
    ok(
        &api.post_up(
            "/api/user_auth/admin/users/unlock",
            &token,
            &code,
            json!({ "username": "root" }),
        )
        .await,
        "step up",
    );
    let replay = api
        .post_up(
            "/api/user_auth/admin/users/unlock",
            &token2,
            &code,
            json!({ "username": "root" }),
        )
        .await;
    assert_eq!(replay.body["code"], "STEP_UP_REPLAYED", "{}", replay.text);

    let init = api
        .post(
            "/api/user_auth/admin/keys/init",
            &token,
            json!({ "passphrase": PASS }),
        )
        .await;
    ok(&init, "keyring init in the elevated session");
    assert_eq!(init.body["enrolled"].as_array().unwrap().len(), 2);
    let first_code = init.body["recovery"]["code"].as_str().unwrap().to_string();

    // The stepped-up session works on without another code for a while.
    let issued = api
        .post(
            "/api/user_auth/admin/keys/recovery_codes",
            &token,
            json!({ "unlock": { "passphrase": PASS }, "label": "drawer" }),
        )
        .await;
    ok(&issued, "second recovery code");
    assert!(issued.body["kit"]
        .as_str()
        .unwrap()
        .contains("VELD RECOVERY KIT"));
    let second_id = issued.body["id"].as_str().unwrap().to_string();
    ok(
        &api.post(
            "/api/user_auth/admin/keys/revoke",
            &token,
            json!({ "unlock": { "recovery_code": first_code }, "id": second_id }),
        )
        .await,
        "revoke with the first code",
    );
    let wrong = api
        .post(
            "/api/user_auth/admin/keys/recovery_codes",
            &token,
            json!({ "unlock": { "passphrase": "not the passphrase" } }),
        )
        .await;
    assert_eq!(wrong.status, StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(wrong.body["code"], "KEY_OPERATION_REFUSED");

    // A passkey enrolled through the server's page, then used to unlock.
    let start = api
        .post(
            "/api/user_auth/admin/keys/passkey",
            &token,
            json!({ "unlock": { "passphrase": PASS }, "label": "YubiKey" }),
        )
        .await;
    ok(&start, "start a passkey enrolment");
    let path = start.body["path"].as_str().unwrap().to_string();
    let ticket = start.body["ticket"].as_str().unwrap().to_string();
    let page = api.call(Method::GET, &path, None, None, None).await;
    assert_eq!(page.status, StatusCode::OK);
    assert!(
        page.text.contains("Add a passkey to the Veld keyring")
            || page.text.contains("\"mode\":\"enrol\"")
    );
    assert!(page
        .csp
        .as_deref()
        .unwrap_or_default()
        .contains("script-src 'nonce-"));
    let prf = [9u8; 32];
    let posted = api
        .call(
            Method::POST,
            &format!("{path}/result"),
            None,
            None,
            Some(json!({
                "credential_id": "Y3JlZA",
                "prf": base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(prf),
            })),
        )
        .await;
    assert_eq!(posted.status, StatusCode::NO_CONTENT, "{}", posted.text);
    let poll = api
        .get(
            &format!("/api/user_auth/admin/keys/passkey/{ticket}"),
            &token,
        )
        .await;
    assert_eq!(poll.body["state"], "done", "{}", poll.text);
    let passkey_id = poll.body["factor"]["id"].as_str().unwrap().to_string();
    assert_eq!(passkey_id, "passkey:localhost:Y3JlZA");
    let again = api.call(Method::GET, &path, None, None, None).await;
    assert_eq!(
        again.status,
        StatusCode::NOT_FOUND,
        "a ticket is single-use"
    );
    let rotated = api
        .post(
            "/api/user_auth/admin/keys/rotate_data_keys",
            &token,
            json!({ "unlock": { "passkey": {
                "id": passkey_id,
                "secret": [REDACTED],
            } } }),
        )
        .await;
    ok(&rotated, "rotate data keys with the passkey");
    assert!(rotated
        .body
        .as_array()
        .unwrap()
        .iter()
        .all(|e| e["epoch"] == 1));

    // Logins: a user is disabled, refused, enabled, and given a temporary password.
    ok(
        &api.post(
            "/api/user_auth/register",
            &token,
            json!({ "username": "bob", "password": "[REDACTED]" }),
        )
        .await,
        "add bob",
    );
    let bob = api.login("bob", "bob-password-1", None).await.body["session_token"]
        .as_str()
        .unwrap()
        .to_string();
    assert_eq!(
        api.get("/api/user_auth/admin/users", &bob).await.status,
        StatusCode::FORBIDDEN,
        "not an admin"
    );
    let users = api.get("/api/user_auth/admin/users", &token).await;
    assert_eq!(users.body.as_array().unwrap().len(), 2);
    ok(
        &api.post(
            "/api/user_auth/admin/users/disable",
            &token,
            json!({ "username": "bob" }),
        )
        .await,
        "disable bob",
    );
    assert_eq!(
        api.get("/api/user_auth/me", &bob).await.status,
        StatusCode::UNAUTHORIZED,
        "his sessions ended"
    );
    let refused = api.login("bob", "bob-password-1", None).await;
    assert_eq!(refused.body["code"], "ACCOUNT_DISABLED", "{}", refused.text);
    ok(
        &api.post(
            "/api/user_auth/admin/users/enable",
            &token,
            json!({ "username": "bob" }),
        )
        .await,
        "enable bob",
    );
    let reset = api
        .post(
            "/api/user_auth/admin/users/reset_password",
            &token,
            json!({ "username": "bob" }),
        )
        .await;
    ok(&reset, "reset bob's password");
    let temporary = reset.body["temporary_password"].as_str().unwrap();
    ok(
        &api.login("bob", temporary, None).await,
        "sign in with the temporary password",
    );
    assert_eq!(
        api.login("bob", "bob-password-1", None).await.status,
        StatusCode::UNAUTHORIZED
    );

    let audit = api.get("/api/user_auth/admin/audit?limit=50", &token).await;
    ok(&audit, "audit");
    let actions: Vec<_> = audit
        .body
        .as_array()
        .unwrap()
        .iter()
        .map(|e| e["action"].as_str().unwrap().to_string())
        .collect();
    for expected in [
        "keyring_init",
        "recovery_code_issued",
        "key_factor_revoked",
        "key_factor_enrolled",
        "data_keys_rotated",
        "user_disable",
        "user_enable",
        "password_reset_by_admin",
    ] {
        assert!(
            actions.iter().any(|a| a == expected),
            "{expected} missing from {actions:?}"
        );
    }
    assert_eq!(actions[0], "password_reset_by_admin", "newest first");
}

import { describe, expect, it } from "vitest";
import {
  isLocalHostFromUrl,
  shouldWarnInsecureApiUrl,
  serializeAndValidateBody,
  nextReconnectDelay,
} from "../security-utils";

// =============================================================================
// isLocalHostFromUrl
// =============================================================================
describe("isLocalHostFromUrl", () => {
  it("returns true for localhost", () => {
    expect(isLocalHostFromUrl("http://localhost:3030")).toBe(true);
  });

  it("returns true for 127.0.0.1", () => {
    expect(isLocalHostFromUrl("http://127.0.0.1:3030")).toBe(true);
  });

  it("returns false for ::1 with brackets (URL parser includes brackets)", () => {
    // Note: new URL("http://[::1]:3030").hostname === "[::1]" in Node.js
    // The implementation checks for "::1" without brackets, so this is false
    expect(isLocalHostFromUrl("http://[::1]:3030")).toBe(false);
  });

  it("returns true for 0.0.0.0", () => {
    expect(isLocalHostFromUrl("http://0.0.0.0:3030")).toBe(true);
  });

  it("returns false for remote URLs", () => {
    expect(isLocalHostFromUrl("https://example.com/api")).toBe(false);
  });

  it("returns false for invalid URL (catch branch)", () => {
    expect(isLocalHostFromUrl("not a url")).toBe(false);
  });

  it("returns false for empty string", () => {
    expect(isLocalHostFromUrl("")).toBe(false);
  });
});

// =============================================================================
// shouldWarnInsecureApiUrl
// =============================================================================
describe("shouldWarnInsecureApiUrl", () => {
  it("warns for remote http URLs by default", () => {
    expect(shouldWarnInsecureApiUrl("http://example.com/api")).toBe(true);
  });

  it("does not warn when allowHttpEnv is 'true'", () => {
    expect(shouldWarnInsecureApiUrl("http://example.com/api", "true")).toBe(false);
  });

  it("does not warn for localhost over http", () => {
    expect(shouldWarnInsecureApiUrl("http://localhost:3030")).toBe(false);
  });

  it("does not warn for https URLs (even remote)", () => {
    expect(shouldWarnInsecureApiUrl("https://example.com/api")).toBe(false);
  });

  it("does not warn for 127.0.0.1 over http", () => {
    expect(shouldWarnInsecureApiUrl("http://127.0.0.1:3030")).toBe(false);
  });

  it("warns when allowHttpEnv is undefined (default)", () => {
    expect(shouldWarnInsecureApiUrl("http://remote.server.com")).toBe(true);
  });

  it("warns when allowHttpEnv is 'false' (not 'true')", () => {
    expect(shouldWarnInsecureApiUrl("http://remote.server.com", "false")).toBe(true);
  });
});

// =============================================================================
// serializeAndValidateBody
// =============================================================================
describe("serializeAndValidateBody", () => {
  it("accepts a small payload", () => {
    const result = serializeAndValidateBody({ message: "ok" }, 100);
    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.serialized).toContain("message");
    }
  });

  it("rejects an oversized payload", () => {
    const result = serializeAndValidateBody({ data: "x".repeat(100) }, 20);
    expect(result.ok).toBe(false);
    // tsconfig `strict: false` disables negative discriminant narrowing
    // (`!result.ok`), so assert the failure shape explicitly.
    const failure = result as { ok: false; error: string };
    expect(failure.error).toContain("exceeds maximum length");
  });

  it("accepts payload at exact boundary", () => {
    const obj = { a: "b" };
    const expectedLen = JSON.stringify(obj).length;
    const result = serializeAndValidateBody(obj, expectedLen);
    expect(result.ok).toBe(true);
  });

  it("rejects payload one byte over boundary", () => {
    const obj = { a: "b" };
    const exactLen = JSON.stringify(obj).length;
    const result = serializeAndValidateBody(obj, exactLen - 1);
    expect(result.ok).toBe(false);
  });

  it("handles empty object", () => {
    const result = serializeAndValidateBody({}, 100);
    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.serialized).toBe("{}");
    }
  });

  it("handles nested objects", () => {
    const result = serializeAndValidateBody({ a: { b: { c: 1 } } }, 10000);
    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(JSON.parse(result.serialized)).toEqual({ a: { b: { c: 1 } } });
    }
  });
});

// =============================================================================
// nextReconnectDelay
// =============================================================================
describe("nextReconnectDelay", () => {
  it("doubles reconnect delay from 1s", () => {
    expect(nextReconnectDelay(1000, 60000)).toBe(2000);
  });

  it("doubles from 2s to 4s", () => {
    expect(nextReconnectDelay(2000, 60000)).toBe(4000);
  });

  it("caps reconnect delay at max", () => {
    expect(nextReconnectDelay(60000, 60000)).toBe(60000);
  });

  it("caps when current exceeds max", () => {
    expect(nextReconnectDelay(70000, 60000)).toBe(60000);
  });

  it("enforces minimum of 1000ms before doubling", () => {
    // safeCurrent = Math.max(500, 1000) = 1000, then 1000*2 = 2000
    expect(nextReconnectDelay(500, 60000)).toBe(2000);
  });

  it("enforces minimum for zero input", () => {
    expect(nextReconnectDelay(0, 60000)).toBe(2000);
  });

  it("enforces minimum for negative input", () => {
    expect(nextReconnectDelay(-100, 60000)).toBe(2000);
  });

  it("handles small max delay", () => {
    expect(nextReconnectDelay(1000, 1500)).toBe(1500);
  });
});

//! One store per backend, so a consumer's tests run the same assertions on each.
//!
//! Every handle here is built from a live database, never reopened by path —
//! the same constraint production construction obeys.

use std::sync::Arc;

use tempfile::TempDir;

use crate::config::StorageBackend;
use crate::storage::ColumnStore;

/// A fresh [`ColumnStore`] per backend with `families` available. The
/// `TempDir` must outlive the store.
pub(crate) fn column_stores(
    families: &[&str],
) -> Vec<(StorageBackend, Arc<dyn ColumnStore>, TempDir)> {
    let mut out: Vec<(StorageBackend, Arc<dyn ColumnStore>, TempDir)> = Vec::new();
    #[cfg(not(feature = "rocksdb"))]
    let _ = families;

    #[cfg(feature = "rocksdb")]
    {
        let tmp = TempDir::new().unwrap();
        let mut opts = rocksdb::Options::default();
        opts.create_if_missing(true);
        opts.create_missing_column_families(true);
        let mut names = vec!["default"];
        names.extend(families.iter().copied());
        let db = rocksdb::DB::open_cf(&opts, tmp.path(), names).unwrap();
        out.push((
            StorageBackend::RocksDb,
            Arc::new(crate::storage::legacy_rocksdb::RocksDbColumnStore::new(
                Arc::new(db),
            )),
            tmp,
        ));
    }

    #[cfg(feature = "storage-redb")]
    {
        let tmp = TempDir::new().unwrap();
        let database =
            crate::storage::redb::create_redb_database_for_test(&tmp.path().join("t.redb"))
                .unwrap();
        out.push((
            StorageBackend::Redb,
            Arc::new(crate::storage::redb::RedbColumnStore::new(database)),
            tmp,
        ));
    }

    out
}

/// A [`KeyValueStore`] per backend, bound to one family.
///
/// For a store that prefixes its own keys the family name carries no meaning,
/// which is why it is the caller's to choose: what the handle has to answer is
/// the same set of calls on both engines. Production binds the DEFAULT keyspace
/// for several of these stores; a named family is used here because a rocksdb
/// `cf_handle("default")` is not guaranteed across crate versions, and the
/// prefixes the store writes are identical either way.
pub(crate) fn key_value_stores(
    family: &str,
) -> Vec<(
    StorageBackend,
    Arc<dyn crate::storage::KeyValueStore>,
    TempDir,
)> {
    column_stores(&[family])
        .into_iter()
        .map(|(backend, store, tmp)| {
            let kv: Arc<dyn crate::storage::KeyValueStore> =
                Arc::new(crate::storage::FamilyKeyValueStore::new(store, family).unwrap());
            (backend, kv, tmp)
        })
        .collect()
}

/// A fresh [`PrimaryMemoryStore`] per backend, each opened the way production opens it.
pub(crate) fn primary_stores() -> Vec<(
    StorageBackend,
    Arc<dyn crate::storage::PrimaryMemoryStore>,
    TempDir,
)> {
    let mut out: Vec<(
        StorageBackend,
        Arc<dyn crate::storage::PrimaryMemoryStore>,
        TempDir,
    )> = Vec::new();

    #[cfg(feature = "rocksdb")]
    {
        let tmp = TempDir::new().unwrap();
        let store =
            crate::storage::legacy_rocksdb::RocksDbPrimaryMemoryStore::open(tmp.path(), None)
                .unwrap();
        out.push((StorageBackend::RocksDb, Arc::new(store), tmp));
    }

    #[cfg(feature = "storage-redb")]
    {
        let tmp = TempDir::new().unwrap();
        let store = crate::storage::redb::RedbPrimaryMemoryStore::open(tmp.path()).unwrap();
        out.push((StorageBackend::Redb, Arc::new(store), tmp));
    }

    out
}

/// Refuses a run that silently dropped a backend this build enables: a loop over
/// one store passes every assertion while proving nothing about the other.
pub(crate) fn assert_both_backends<T>(stores: &[(StorageBackend, T, TempDir)]) {
    let backends: Vec<StorageBackend> = stores.iter().map(|(b, _, _)| *b).collect();
    #[cfg(feature = "rocksdb")]
    assert!(
        backends.contains(&StorageBackend::RocksDb),
        "no rocksdb store under test"
    );
    #[cfg(feature = "storage-redb")]
    assert!(
        backends.contains(&StorageBackend::Redb),
        "no redb store under test"
    );
}

export function isLocalHostFromUrl(apiUrl: string): boolean {
  try {
    const url = new URL(apiUrl);
    const host = url.hostname;
    return host === "127.0.0.1" || host === "localhost" || host === "::1" || host === "0.0.0.0";
  } catch {
    return false;
  }
}

export function shouldWarnInsecureApiUrl(apiUrl: string, allowHttpEnv?: string): boolean {
  return !isLocalHostFromUrl(apiUrl) && apiUrl.startsWith("http://") && allowHttpEnv !== "true";
}

export function serializeAndValidateBody(body: object, maxLength: number): { ok: true; serialized: string } | { ok: false; error: string } {
  const serialized = JSON.stringify(body);
  if (serialized.length > maxLength) {
    return { ok: false, error: `Request body exceeds maximum length of ${maxLength} characters` };
  }
  return { ok: true, serialized };
}

export function nextReconnectDelay(currentDelayMs: number, maxDelayMs: number): number {
  const safeCurrent = Math.max(currentDelayMs, 1000);
  return Math.min(safeCurrent * 2, maxDelayMs);
}

//! P1.6: Distributed tracing with OpenTelemetry (OPTIONAL)
//!
//! Enables distributed tracing for production observability:
//! - End-to-end request tracking across services
//! - Performance bottleneck identification
//! - Latency analysis per operation
//! - Integration with Jaeger, Tempo, or any OTLP-compatible backend
//!
//! **Feature flag: `telemetry`**
//! - Enable with: `cargo build --features telemetry`
//! - Disabled by default for edge devices (saves ~200 packages)

#[cfg(feature = "telemetry")]
use opentelemetry::{global, trace::TracerProvider as _, KeyValue};
#[cfg(feature = "telemetry")]
use opentelemetry_otlp::{SpanExporter, WithExportConfig};
#[cfg(feature = "telemetry")]
use opentelemetry_sdk::{
    trace::{RandomIdGenerator, Sampler, TracerProvider},
    Resource,
};
#[cfg(feature = "telemetry")]
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt, EnvFilter};

/// Global tracer provider for shutdown
#[cfg(feature = "telemetry")]
static TRACER_PROVIDER: std::sync::OnceLock<TracerProvider> = std::sync::OnceLock::new();

/// Initialize distributed tracing with OpenTelemetry
///
/// Configuration via environment variables:
/// - OTEL_EXPORTER_OTLP_ENDPOINT: OTLP endpoint (default: http://localhost:4317)
/// - OTEL_SERVICE_NAME: Service name (default: veld)
/// - OTEL_TRACE_SAMPLER: Sampling strategy (default: parentbased_always_on)
/// - RUST_LOG: Log level filter (default: info)
#[cfg(feature = "telemetry")]
pub fn init_tracing() -> Result<(), Box<dyn std::error::Error>> {
    // Read configuration from environment
    let otlp_endpoint = std::env::var("OTEL_EXPORTER_OTLP_ENDPOINT")
        .unwrap_or_else(|_| "http://localhost:4317".to_string());

    let service_name = std::env::var("OTEL_SERVICE_NAME").unwrap_or_else(|_| "veld".to_string());

    // Build span exporter using the new builder API (opentelemetry 0.27+)
    let exporter = SpanExporter::builder()
        .with_tonic()
        .with_endpoint(&otlp_endpoint)
        .build()?;

    // Build resource with service metadata
    let resource = Resource::new(vec![
        KeyValue::new("service.name", service_name.clone()),
        KeyValue::new("service.version", env!("VELD_VERSION_FULL")),
    ]);

    // Build tracer provider using the new builder API
    let tracer_provider = TracerProvider::builder()
        .with_batch_exporter(exporter, opentelemetry_sdk::runtime::Tokio)
        .with_sampler(Sampler::ParentBased(Box::new(Sampler::AlwaysOn)))
        .with_id_generator(RandomIdGenerator::default())
        .with_resource(resource)
        .build();

    // Get tracer from provider
    let tracer = tracer_provider.tracer("veld");

    // Store provider for shutdown
    let _ = TRACER_PROVIDER.set(tracer_provider.clone());

    // Set as global provider
    global::set_tracer_provider(tracer_provider);

    // Create OpenTelemetry tracing layer
    let telemetry_layer = tracing_opentelemetry::layer().with_tracer(tracer);

    // Configure log filter (RUST_LOG env var or default to info)
    let env_filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));

    // Set up tracing subscriber with both console and OpenTelemetry layers
    tracing_subscriber::registry()
        .with(env_filter)
        .with(tracing_subscriber::fmt::layer())
        .with(telemetry_layer)
        .init();

    tracing::info!(
        service_name = %service_name,
        otlp_endpoint = %otlp_endpoint,
        "OpenTelemetry tracing initialized"
    );

    Ok(())
}

/// Shutdown tracing and flush remaining spans
///
/// Call this during graceful shutdown to ensure all traces are exported
#[cfg(feature = "telemetry")]
pub fn shutdown_tracing() {
    tracing::info!("Shutting down OpenTelemetry tracing");
    if let Some(provider) = TRACER_PROVIDER.get() {
        if let Err(e) = provider.shutdown() {
            tracing::error!("Error shutting down tracer provider: {:?}", e);
        }
    }
}

/// Middleware for propagating trace context through HTTP headers
///
/// Extracts trace context from incoming requests and injects it into outgoing requests
/// following W3C Trace Context specification (traceparent/tracestate headers)
#[cfg(feature = "telemetry")]
pub mod trace_propagation {
    use axum::{extract::Request, middleware::Next, response::Response};
    use opentelemetry::global;
    use opentelemetry::propagation::Extractor;
    use tracing::Span;
    use tracing_opentelemetry::OpenTelemetrySpanExt;

    /// HTTP header extractor for OpenTelemetry context propagation
    struct HeaderExtractor<'a> {
        headers: &'a axum::http::HeaderMap,
    }

    impl<'a> Extractor for HeaderExtractor<'a> {
        fn get(&self, key: &str) -> Option<&str> {
            self.headers.get(key)?.to_str().ok()
        }

        fn keys(&self) -> Vec<&str> {
            self.headers.keys().map(|k| k.as_str()).collect()
        }
    }

    /// Middleware to extract trace context from HTTP headers
    pub async fn propagate_trace_context(req: Request, next: Next) -> Response {
        // Extract parent trace context from headers
        let extractor = HeaderExtractor {
            headers: req.headers(),
        };
        let parent_cx =
            global::get_text_map_propagator(|propagator| propagator.extract(&extractor));

        // Set parent context on current span
        let current_span = Span::current();
        current_span.set_parent(parent_cx);

        // Continue processing
        next.run(req).await
    }
}

#[cfg(all(test, feature = "telemetry"))]
mod tests {
    use super::*;

    #[test]
    fn test_tracing_init_no_panic() {
        // Test that init doesn't panic even if OTLP endpoint is unavailable
        // In production, traces will be buffered and retried
        let _ = init_tracing();
    }
}

//! gen-mcp-tools — parse `mcp-server/index.ts` and emit a markdown reference
//! page listing every MCP tool with description and schema.
//!
//! The TypeScript registrations use a consistent pattern:
//!
//!     server.registerTool(
//!       "tool_name",
//!       { description: "...", inputSchema: z.object({...}) },
//!       async (...) => { ... }
//!     )
//!
//! or via the rmcp-style:
//!
//!     name: "tool_name",
//!     description: "...",
//!     ...
//!
//! We use targeted regex to extract `name`+`description` pairs. If the count
//! drops below an expected lower-bound (45), we fail loudly.

use anyhow::Result;
use regex::Regex;

use veld_docs_generators::{
    docs_src_root, generated_header, read_source, repo_root, write_output,
};

const MIN_EXPECTED_TOOLS: usize = 45;

#[derive(Debug, Clone)]
struct McpTool {
    name: String,
    description: String,
}

fn extract_tools(source: &str) -> Vec<McpTool> {
    // Match either:
    //   name: "tool_name", ... description: "..."
    // or:
    //   registerTool("tool_name", { description: "..." }, ...)
    //
    // We do this in two passes and dedupe by name (server name "veld" is excluded).
    let pair_re =
        Regex::new(r#"name:\s*"([a-z_][a-z0-9_]*)"\s*,[\s\S]{0,400}?description:\s*"([^"]+)""#)
            .expect("regex");
    let register_re =
        Regex::new(r#"registerTool\(\s*"([a-z_][a-z0-9_]*)"\s*,[\s\S]{0,400}?description:\s*"([^"]+)""#)
            .expect("regex");

    let mut seen: std::collections::BTreeMap<String, String> = std::collections::BTreeMap::new();
    for cap in pair_re.captures_iter(source) {
        let name = cap[1].to_string();
        if name == "veld" {
            continue;
        } // server name, not a tool
        let desc = cap[2].to_string();
        seen.entry(name).or_insert(desc);
    }
    for cap in register_re.captures_iter(source) {
        let name = cap[1].to_string();
        if name == "veld" {
            continue;
        }
        let desc = cap[2].to_string();
        seen.entry(name).or_insert(desc);
    }

    seen.into_iter()
        .map(|(name, description)| McpTool { name, description })
        .collect()
}

fn render(tools: &[McpTool]) -> String {
    let mut out = generated_header("mcp-server/index.ts", "gen-mcp-tools");
    out.push_str("# MCP Tools\n\n");
    out.push_str(&format!(
        "The TypeScript MCP server (`@veld/memory-mcp`) exposes **{}** tools over the HTTP API. The Rust binary (`veld serve`) exposes the same tools via stdio MCP using `rmcp`.\n\n",
        tools.len()
    ));
    out.push_str("Tools are listed alphabetically. For full parameter schemas, see [mcp-server/index.ts](https://github.com/Portll/veld/blob/main/mcp-server/index.ts).\n\n");
    out.push_str("| Tool | Description |\n|---|---|\n");
    let mut sorted: Vec<&McpTool> = tools.iter().collect();
    sorted.sort_by(|a, b| a.name.cmp(&b.name));
    for t in sorted {
        // Escape pipes inside descriptions for markdown table cells.
        let safe_desc = t.description.replace('|', "\\|").replace('\n', " ");
        out.push_str(&format!("| `{}` | {} |\n", t.name, safe_desc));
    }
    out.push_str("\n---\n\n*To use these from Claude Code or VS Code Copilot, see the [Claude Code integration guide](../guides/claude-code-integration.md) or [VS Code Copilot guide](../guides/vscode-copilot.md).*\n");
    out
}

fn main() -> Result<()> {
    let index_path = repo_root().join("mcp-server").join("index.ts");
    let source = read_source(&index_path)?;
    let tools = extract_tools(&source);

    if tools.len() < MIN_EXPECTED_TOOLS {
        anyhow::bail!(
            "extracted only {} MCP tools from {}, expected at least {}. The registration pattern may have changed; inspect the generator.",
            tools.len(),
            index_path.display(),
            MIN_EXPECTED_TOOLS
        );
    }

    let output_path = docs_src_root().join("reference").join("mcp-tools.md");
    write_output(&output_path, &render(&tools))?;

    eprintln!("gen-mcp-tools: extracted {} tools", tools.len());
    Ok(())
}

//! gen-http-api — parse `src/handlers/router.rs` and emit a markdown reference
//! page listing every HTTP endpoint with method, path, and handler.
//!
//! Strategy: walk the syn AST looking for chained `.route("/path", METHOD(handler))`
//! calls. The Axum router uses this pattern throughout. Non-literal paths
//! (rare) are skipped with a warning comment.

use anyhow::{Context, Result};
use std::collections::BTreeMap;
use syn::visit::Visit;
use syn::{Expr, ExprCall, ExprMethodCall, ExprPath, Lit};

use veld_docs_generators::{
    docs_src_root, generated_header, read_source, repo_root, write_output,
};

#[derive(Debug, Clone)]
struct Route {
    method: String,
    path: String,
    handler: String,
}

struct RouteCollector {
    routes: Vec<Route>,
    skipped: usize,
}

impl<'ast> Visit<'ast> for RouteCollector {
    fn visit_expr_method_call(&mut self, call: &'ast ExprMethodCall) {
        if call.method == "route" && call.args.len() == 2 {
            // First arg: literal string for the path.
            let path = match &call.args[0] {
                Expr::Lit(lit) => match &lit.lit {
                    Lit::Str(s) => Some(s.value()),
                    _ => None,
                },
                _ => None,
            };

            // Second arg: METHOD(handler) call where METHOD is get/post/put/delete/patch.
            let (method, handler) = match &call.args[1] {
                Expr::Call(ExprCall { func, args, .. }) => {
                    let m = match func.as_ref() {
                        Expr::Path(ExprPath { path, .. }) => {
                            path.segments.last().map(|s| s.ident.to_string())
                        }
                        _ => None,
                    };
                    let h = args.first().and_then(|a| match a {
                        Expr::Path(ExprPath { path, .. }) => Some(
                            path.segments
                                .iter()
                                .map(|s| s.ident.to_string())
                                .collect::<Vec<_>>()
                                .join("::"),
                        ),
                        _ => None,
                    });
                    (m, h)
                }
                _ => (None, None),
            };

            match (path, method, handler) {
                (Some(p), Some(m), Some(h)) => self.routes.push(Route {
                    method: m.to_uppercase(),
                    path: p,
                    handler: h,
                }),
                _ => self.skipped += 1,
            }
        }
        syn::visit::visit_expr_method_call(self, call);
    }
}

fn render(routes: &[Route], skipped: usize) -> String {
    let mut out = generated_header("src/handlers/router.rs", "gen-http-api");
    out.push_str("# HTTP API\n\n");
    out.push_str(&format!(
        "Veld exposes **{}** HTTP routes. Every route (except `/health/*` probes) requires API-key authentication via the `X-API-Key` header.\n\n",
        routes.len()
    ));
    if skipped > 0 {
        out.push_str(&format!(
            "> Warning: {skipped} route(s) used a non-literal path string and were skipped by the generator. \
             Inspect [src/handlers/router.rs](https://github.com/Portll/veld/blob/main/src/handlers/router.rs) directly for those.\n\n"
        ));
    }
    out.push_str("Base URL: `http://127.0.0.1:3030` (default; configurable via `VELD_BIND_ADDR`).\n\n");

    // Group by path prefix for readability: /api/X/* → "X", /health/* → "health", etc.
    let mut groups: BTreeMap<String, Vec<&Route>> = BTreeMap::new();
    for r in routes {
        let group = match r.path.strip_prefix("/api/") {
            Some(rest) => {
                let seg = rest.split('/').next().unwrap_or("misc");
                if seg.is_empty() {
                    "misc".to_string()
                } else {
                    seg.to_string()
                }
            }
            None => match r.path.strip_prefix('/') {
                Some(rest) => rest.split('/').next().unwrap_or("misc").to_string(),
                None => "misc".to_string(),
            },
        };
        groups.entry(group).or_default().push(r);
    }

    for (group, rs) in &groups {
        out.push_str(&format!("## /{}\n\n", group));
        out.push_str("| Method | Path | Handler |\n|---|---|---|\n");
        let mut sorted = rs.clone();
        sorted.sort_by(|a, b| a.path.cmp(&b.path));
        for r in sorted {
            out.push_str(&format!(
                "| `{}` | `{}` | `{}` |\n",
                r.method, r.path, r.handler
            ));
        }
        out.push('\n');
    }

    out.push_str(
        "---\n\n*Handlers live in `src/handlers/*.rs`. For request/response shapes, see the corresponding handler source or run `veld serve` and call `OPTIONS /api/...` (where supported).*\n",
    );
    out
}

fn main() -> Result<()> {
    let router_path = repo_root().join("src").join("handlers").join("router.rs");
    let source = read_source(&router_path)?;
    let file = syn::parse_file(&source)
        .with_context(|| format!("parsing {}", router_path.display()))?;

    let mut collector = RouteCollector {
        routes: Vec::new(),
        skipped: 0,
    };
    collector.visit_file(&file);

    if collector.routes.is_empty() {
        anyhow::bail!(
            "extracted zero routes from {} — the router pattern may have changed; \
             inspect the generator",
            router_path.display()
        );
    }

    let output_path = docs_src_root().join("reference").join("http-api.md");
    write_output(&output_path, &render(&collector.routes, collector.skipped))?;

    eprintln!(
        "gen-http-api: extracted {} routes ({} skipped)",
        collector.routes.len(),
        collector.skipped
    );
    Ok(())
}

// Security tab: sign in to veld's user-auth surface, then manage the keyring and
// the logins of the instance in the active tab.
//
// The session token lives in this module's memory only. Every change asks for a
// fresh 2FA code (step-up); every key change also asks for something that opens the
// keyring: the passphrase, a recovery code, or Touch ID on this Mac.

const { invoke } = window.__TAURI__.core;

const state = { session: null, me: null, view: "keys", enclave: null };

const base = () => (window.veldActiveBaseUrl?.() || "").replace(/\/+$/, "");
const $ = (id) => document.getElementById(id);

function h(tag, attrs = {}, ...children) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v === undefined || v === null || v === false) continue;
    if (k === "class") el.className = v;
    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
    else if (v === true) el.setAttribute(k, "");
    else el.setAttribute(k, v);
  }
  for (const c of children.flat()) {
    if (c === undefined || c === null || c === false) continue;
    el.append(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return el;
}

const when = (iso) => (iso ? new Date(iso).toLocaleString() : "—");

class ApiError extends Error {
  constructor(status, body) {
    super(body?.message || (typeof body === "string" ? body : `HTTP ${status}`));
    this.status = status;
    this.code = body?.code;
  }
}

async function api(method, path, { body, stepUp } = {}) {
  const res = await invoke("security_request", {
    baseUrl: base(),
    method,
    path,
    session: state.session,
    stepUp: stepUp || null,
    body: body ?? null,
  });
  if (res.status >= 400) {
    const err = new ApiError(res.status, res.body);
    if (err.code === "INVALID_SESSION" && state.session) signOut("Your session ended. Sign in again.");
    throw err;
  }
  return res.body;
}

// ── Modals ──────────────────────────────────────────────────────────────

function modal(title, body, actions) {
  const root = $("sec-modal");
  root.replaceChildren(
    h("div", { class: "sec-modal-card", role: "dialog", "aria-modal": "true", "aria-label": title },
      h("h3", {}, title), body, h("div", { class: "sec-modal-actions" }, actions)),
  );
  root.classList.remove("hidden");
  const first = root.querySelector("input, select, button");
  first?.focus();
  return () => root.classList.add("hidden");
}

// Ask for some values. Resolves to an object keyed by field name, or null if cancelled.
function ask(title, fields, { submit = "Continue", note } = {}) {
  return new Promise((resolve) => {
    const inputs = {};
    const form = h("form", { class: "sec-form" },
      note ? h("p", { class: "sec-note" }, note) : null,
      fields.map((f) => {
        const input = f.options
          ? h("select", { name: f.name }, f.options.map((o) => h("option", { value: o.value }, o.label)))
          : h("input", {
              name: f.name, type: f.type || "text", placeholder: f.placeholder || "",
              autocomplete: f.autocomplete || "off", inputmode: f.inputmode, required: f.optional ? false : true,
            });
        if (f.value !== undefined) input.value = f.value;
        inputs[f.name] = input;
        return h("label", {}, h("span", {}, f.label), input);
      }));
    let close;
    const done = (value) => { close(); resolve(value); };
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      done(Object.fromEntries(Object.entries(inputs).map(([k, el]) => [k, el.value])));
    });
    close = modal(title, form, [
      h("button", { type: "button", class: "sec-secondary", onclick: () => done(null) }, "Cancel"),
      h("button", { type: "button", onclick: () => form.requestSubmit() }, submit),
    ]);
  });
}

function show(title, ...content) {
  return new Promise((resolve) => {
    let close;
    close = modal(title, h("div", {}, content), [
      h("button", { type: "button", onclick: () => { close(); resolve(); } }, "Done"),
    ]);
  });
}

function confirmAction(title, text, verb) {
  return new Promise((resolve) => {
    let close;
    close = modal(title, h("p", {}, text), [
      h("button", { type: "button", class: "sec-secondary", onclick: () => { close(); resolve(false); } }, "Cancel"),
      h("button", { type: "button", class: "sec-danger", onclick: () => { close(); resolve(true); } }, verb),
    ]);
  });
}

function flash(text, kind = "info") {
  const el = $("sec-flash");
  el.textContent = text;
  el.className = "sec-flash " + kind;
  clearTimeout(flash.timer);
  flash.timer = setTimeout(() => (el.className = "sec-flash hidden"), 6000);
}

// Run a change behind step-up. A session stepped up in the last few minutes passes
// without a code; otherwise ask, and ask again when the code is refused.
async function stepUp(title, run) {
  try {
    return await run(null);
  } catch (err) {
    if (err.code !== "STEP_UP_REQUIRED") throw err;
  }
  for (let attempt = 0; attempt < 3; attempt++) {
    const v = await ask(title, [
      { name: "code", label: "2FA code", placeholder: "123456", inputmode: "numeric", autocomplete: "one-time-code" },
    ], { submit: "Confirm", note: attempt ? "That code was refused or already used. Wait for the next one." : null });
    if (!v) return null;
    try {
      return await run(v.code.trim());
    } catch (err) {
      if (err.code === "STEP_UP_REQUIRED" || err.code === "STEP_UP_REPLAYED") continue;
      throw err;
    }
  }
  return null;
}

// Something that opens the keyring, as the API body's `unlock`.
async function unlockFactor(status, purpose) {
  const enclaveFactors = (status?.keyring?.factors || []).filter((f) => f.provider === "secure-enclave");
  const options = [
    { value: "passphrase", label: "Passphrase" },
    { value: "recovery_code", label: "Recovery code" },
  ];
  if (enclaveFactors.length && state.enclave?.touch_id) {
    for (const f of enclaveFactors) options.push({ value: "se:" + f.id, label: "Touch ID — " + (f.label || f.id) });
  }
  const pick = await ask("Open the keyring", [
    { name: "with", label: "With", options },
  ], { note: purpose });
  if (!pick) return null;
  if (pick.with.startsWith("se:")) {
    const id = pick.with.slice(3);
    const released = await invoke("enclave", { action: "unlock", id });
    return { secure_enclave: { id, secret: [REDACTED] } };
  }
  const secret = await ask(pick.with === "passphrase" ? "Passphrase" : "Recovery code", [
    { name: "value", label: pick.with === "passphrase" ? "Passphrase" : "Recovery code", type: "password" },
  ]);
  return secret ? { [pick.with]: secret.value } : null;
}

async function showKit(issued, title = "Recovery kit") {
  const save = async () => {
    const path = await invoke("save_secret_file", {
      suggestedName: `veld-recovery-kit-${issued.id}.txt`,
      contents: issued.kit,
    });
    if (path) flash("Saved to " + path, "ok");
  };
  await show(title,
    h("p", {}, "This code opens the keyring if the passphrase is lost. It is shown once and never stored by veld."),
    h("pre", { class: "sec-code" }, issued.code.match(/.{1,6}/g).join("-")),
    h("p", { class: "sec-note" }, "Keep it offline and apart from backups of the data directory. Id: " + issued.id),
    h("button", { type: "button", onclick: save }, "Save kit…"));
}

// ── Sign in ─────────────────────────────────────────────────────────────

function signOut(message) {
  const token = [REDACTED];
  state.session = null;
  state.me = null;
  if (token) invoke("security_request", { baseUrl: base(), method: "POST", path: "/api/user_auth/logout", session: token, stepUp: null, body: null }).catch(() => {});
  render();
  if (message) flash(message, "warn");
}

async function refreshMe() {
  state.me = await api("GET", "/api/user_auth/me");
}

function renderSignIn(body) {
  const form = h("form", { class: "sec-form sec-signin" },
    h("h3", {}, "Sign in to " + (base() || "veld")),
    h("label", {}, h("span", {}, "Username"), h("input", { name: "username", required: true, autocomplete: "username" })),
    h("label", {}, h("span", {}, "Password"), h("input", { name: "password", type: "password", required: true, autocomplete: "current-password" })),
    h("label", {}, h("span", {}, "2FA code"), h("input", { name: "totp", inputmode: "numeric", autocomplete: "one-time-code", placeholder: "if enrolled" })),
    h("button", { type: "submit" }, "Sign in"),
    h("p", { class: "sec-note" }, "Key and login management needs an admin account with 2FA. The first account registered on a server becomes its admin."),
    h("button", { type: "button", class: "sec-link", onclick: bootstrap }, "Create the first admin…"));
  form.addEventListener("submit", async (e) => {
    e.preventDefault();
    const f = new FormData(form);
    try {
      const res = await api("POST", "/api/user_auth/login", {
        body: { username: f.get("username"), password: f.get("password"), totp: f.get("totp") || null },
      });
      state.session = res.session_token;
      await refreshMe();
      state.view = state.me.user.role === "admin" ? "keys" : "account";
      render();
    } catch (err) {
      flash(err.code === "USER_AUTH_DISABLED"
        ? "User auth is off on this server: set VELD_USER_AUTH_ENABLED=true and restart it."
        : err.message, "error");
    }
  });
  body.append(form);
}

async function bootstrap() {
  const v = await ask("Create the first admin", [
    { name: "username", label: "Username", autocomplete: "username" },
    { name: "password", label: "Password", type: "password", autocomplete: "new-password" },
  ], { note: "Works only while the server has no accounts. Enrol 2FA right after signing in." });
  if (!v) return;
  try {
    await api("POST", "/api/user_auth/register", { body: v });
    flash("Admin created. Sign in.", "ok");
  } catch (err) {
    flash(err.message, "error");
  }
}

// ── Keys ────────────────────────────────────────────────────────────────

async function keyChange(title, purpose, call, status) {
  try {
    const unlock = await unlockFactor(status, purpose);
    if (!unlock) return null;
    return await stepUp(title, (code) => call(unlock, code));
  } catch (err) {
    flash(err.message || String(err), "error");
    return null;
  }
}

async function renderKeys(body) {
  const res = await api("GET", "/api/user_auth/admin/keys/status");
  const status = res.status;
  if (state.enclave === null) {
    state.enclave = await invoke("enclave", { action: "probe" }).catch(() => ({ secure_enclave: false, touch_id: false }));
  }
  const reload = () => render();

  if (!status.keyring) {
    body.append(h("section", { class: "sec-card" },
      h("h3", {}, "Keyring"),
      h("p", {}, "No keyring yet. A keyring holds the recovery codes, Touch ID and passkeys that can open every keystore on this server, including tenants created later."),
      h("button", { type: "button", onclick: async () => {
        const v = await ask("Set up the keyring", [
          { name: "passphrase", label: "Server passphrase", type: "password" },
          { name: "label", label: "Label for the first recovery code", value: "initial", optional: true },
        ], { note: "The passphrase the server unseals with (VELD_MASTER_PASSPHRASE)." });
        if (!v) return;
        try {
          const out = await stepUp("Confirm keyring setup", (code) =>
            api("POST", "/api/user_auth/admin/keys/init", { body: { passphrase: v.passphrase, label: v.label || null }, stepUp: code }));
          if (out) {
            await showKit(out.recovery, "Keyring created — first recovery kit");
            reload();
          }
        } catch (err) { flash(err.message, "error"); }
      } }, "Set up keyring…")));
  } else {
    if (!res.keyring_unsealed) {
      body.append(h("p", { class: "sec-flash warn" }, "The keyring exists but this server started before it: restart veld so tenants open through it."));
    }
    const factors = status.keyring.factors || [];
    const revoke = (f) => async () => {
      if (!(await confirmAction("Revoke " + (f.label || f.id), "It will no longer open the keyring. Copies of the keyring made before now still open with it.", "Revoke"))) return;
      const out = await keyChange("Confirm revocation", "Revoke " + f.id, (unlock, code) =>
        api("POST", "/api/user_auth/admin/keys/revoke", { body: { unlock, id: f.id }, stepUp: code }), status);
      if (out) { flash("Revoked " + f.id, "ok"); reload(); }
    };
    body.append(h("section", { class: "sec-card" },
      h("h3", {}, "Keyring factors"),
      h("table", { class: "sec-table" },
        h("thead", {}, h("tr", {}, h("th", {}, "Kind"), h("th", {}, "Label"), h("th", {}, "Added"), h("th", {}, ""))),
        h("tbody", {}, factors.map((f) => h("tr", {},
          h("td", {}, f.provider),
          h("td", { title: f.id }, f.label || f.id),
          h("td", {}, when(f.created_at)),
          h("td", {}, f.provider === "passphrase" ? "" : h("button", { type: "button", class: "sec-small sec-danger", onclick: revoke(f) }, "Revoke")))))),
      h("div", { class: "sec-actions" },
        h("button", { type: "button", onclick: async () => {
          const label = await ask("New recovery code", [{ name: "label", label: "Label", placeholder: "e.g. safe at home", optional: true }]);
          if (!label) return;
          const out = await keyChange("Confirm new recovery code", "Issue a recovery code", (unlock, code) =>
            api("POST", "/api/user_auth/admin/keys/recovery_codes", { body: { unlock, label: label.label || null }, stepUp: code }), status);
          if (out) { await showKit(out); reload(); }
        } }, "New recovery kit…"),
        h("button", { type: "button", disabled: !state.enclave?.touch_id, title: state.enclave?.touch_id ? "" : "Touch ID or the veld-enclave helper is not available on this Mac", onclick: async () => {
          const label = await ask("Add Touch ID", [{ name: "label", label: "Label", value: "Touch ID", optional: true }],
            { note: "Creates a key in this Mac's Secure Enclave that only your current fingerprints can use. Adding or removing a fingerprint later invalidates it." });
          if (!label) return;
          const out = await keyChange("Confirm Touch ID", "Enrol Touch ID", async (unlock, code) => {
            const released = await invoke("enclave", { action: "enrol", label: label.label || "Touch ID" });
            return api("POST", "/api/user_auth/admin/keys/factors", {
              body: { unlock, provider: "secure-enclave", id: released.id, label: released.label, secret: [REDACTED] }, stepUp: code });
          }, status);
          if (out) { flash("Touch ID enrolled", "ok"); reload(); }
        } }, "Add Touch ID…"),
        h("button", { type: "button", onclick: async () => {
          const label = await ask("Add a passkey", [{ name: "label", label: "Label", placeholder: "e.g. YubiKey 5C", optional: true }],
            { note: "Opens your browser to create a passkey with the PRF extension (iCloud Keychain on macOS 15+, most security keys)." });
          if (!label) return;
          const out = await keyChange("Confirm passkey", "Enrol a passkey", (unlock, code) =>
            api("POST", "/api/user_auth/admin/keys/passkey", { body: { unlock, label: label.label || null }, stepUp: code }), status);
          if (!out) return;
          const pageUrl = base().replace("://127.0.0.1", "://localhost").replace("://[::1]", "://localhost") + out.path;
          await invoke("open_in_browser", { url: pageUrl });
          flash("Finish in the browser…", "info");
          for (let i = 0; i < 150; i++) {
            await new Promise((r) => setTimeout(r, 2000));
            const poll = await api("GET", "/api/user_auth/admin/keys/passkey/" + out.ticket).catch(() => null);
            if (!poll || poll.state === "waiting") continue;
            if (poll.state === "done") flash("Passkey enrolled", "ok");
            else flash("Passkey not enrolled: " + poll.error, "error");
            return reload();
          }
          flash("The passkey step timed out.", "error");
        } }, "Add passkey…")),
    ));

    body.append(h("section", { class: "sec-card" },
      h("h3", {}, "Rotation"),
      h("div", { class: "sec-actions" },
        h("button", { type: "button", onclick: async () => {
          const v = await ask("Rotate the passphrase", [
            { name: "old", label: "Current passphrase", type: "password" },
            { name: "new", label: "New passphrase", type: "password" },
            { name: "again", label: "New passphrase again", type: "password" },
          ], { note: "Re-wraps the keyring and every keystore. Set the new passphrase where veld reads it before the next restart." });
          if (!v) return;
          if (v.new !== v.again) return flash("The new passphrases differ.", "error");
          try {
            const out = await stepUp("Confirm passphrase rotation", (code) =>
              api("POST", "/api/user_auth/admin/keys/rotate_passphrase", { body: { old: v.old, new: v.new }, stepUp: code }));
            if (out) flash(`Passphrase rotated on the keyring and ${out.keystores.length} keystore(s).`, "ok");
          } catch (err) { flash(err.message, "error"); }
        } }, "Rotate passphrase…"),
        h("button", { type: "button", onclick: async () => {
          const out = await keyChange("Confirm data-key rotation", "Start a new data-key epoch everywhere", (unlock, code) =>
            api("POST", "/api/user_auth/admin/keys/rotate_data_keys", { body: { unlock }, stepUp: code }), status);
          if (out) { flash(`New data-key epoch in ${out.length} keystore(s).`, "ok"); reload(); }
        } }, "Rotate data keys…"),
        h("button", { type: "button", class: "sec-danger", onclick: async () => {
          if (!(await confirmAction("Rotate every master key",
            "Every master key is replaced. Data, purpose keys and the index carry over, but every recovery code, Touch ID and passkey is dropped; a new recovery kit is issued.", "Rotate"))) return;
          const v = await ask("Passphrase", [{ name: "passphrase", label: "Server passphrase", type: "password" }]);
          if (!v) return;
          try {
            const out = await stepUp("Confirm master-key rotation", (code) =>
              api("POST", "/api/user_auth/admin/keys/rotate_master_keys", { body: { passphrase: v.passphrase, label: null }, stepUp: code }));
            if (out) { await showKit(out.recovery, "Master keys rotated — new recovery kit"); reload(); }
          } catch (err) { flash(err.message, "error"); }
        } }, "Rotate master keys…"))));
  }

  body.append(h("section", { class: "sec-card" },
    h("h3", {}, "Keystores"),
    h("table", { class: "sec-table" },
      h("thead", {}, h("tr", {}, h("th", {}, "Scope"), h("th", {}, "Data-key epochs"), h("th", {}, "Keyring"), h("th", {}, "Generation"))),
      h("tbody", {}, status.keystores.map((k) => h("tr", { title: k.path },
        h("td", {}, k.scope),
        h("td", {}, k.error ? h("span", { class: "sec-bad" }, k.error) : `${k.epochs.join(", ")} (active ${k.active_epoch})`),
        h("td", {}, k.ring ? "✓" : h("span", { class: "sec-bad" }, "not enrolled")),
        h("td", {}, k.generation ?? "—")))))));
}

